mapper.select:
select t.id, t.tenant_id, t.dept_id, t.device_code, d.dept_name,t.industry_code
from vm_organ_device_rel_t t left join sys_dept d on t.dept_id = d.dept_id and d.del_flag='0'
where t.delete_flag='0'
and t.tenant_id = #{tenantId}

    and t.industry_code = #{industryCode}


    and t.device_code like CONCAT('%', #{deviceCode}, '%')


    and t.device_type = #{deviceType}

select rel.device_code,
       rel.device_name
from vm_tenant_device_common_rel_t rel
where rel.device_code = #{deviceCode}
  and rel.tenant_id = #{tenantId}
  and rel.industry_code = #{industryCode}
  and rel.device_type = '3'
  and rel.delete_flag = '0'

mapper.update:
update vm_tenant_device_common_rel_t
set device_name = #{deviceName},
    modifier = #{modifier},
    update_time = now()
where
    device_code = #{deviceCode}
  and tenant_id = #{tenantId}
  and industry_code = #{industryCode}
  and device_type = #{deviceType}
  and delete_flag = '0'

mapper.select:
select a.* from (SELECT distinct dev.device_code, (case when length(IFNULL(rel.device_name, '')) = 0 then dev.device_name else rel.device_name end) as device_name, dev.device_status as status, dev.location, dev.latitude, dev.longitude, dev.site_code, dev.model_code FROM vm_recorder_device_info_t dev left join vm_order_recorder_devices t1 on dev.device_code = t1.device_code left join vm_tenant_device_common_rel_t rel ON rel.device_code = t1.device_code and rel.tenant_id = t1.tenant_id and rel.industry_code = t1.industry_code and rel.delete_flag = '0' and rel.device_type = 3 where t1.delete_flag = '0' and dev.delete_flag = '0' and t1.ord_status in (0,1,2)
AND dev.site_code = #{param.siteCode}
AND dev.latitude = #{param.latitude}
AND dev.longitude = #{param.longitude}
${param.dataScope}) a order by CONVERT(a.device_name USING GBK) asc

select t.device_code, (case when length(IFNULL(rel.device_name, '')) = 0 then t.device_name else rel.device_name end ) name, t.location, ST_Distance_Sphere( ST_GeomFromText(CONCAT('POINT(',#{param.longitude},' ',#{param.latitude},')')), ST_GeomFromText(CONCAT('POINT(',t.longitude,' ',t.latitude,')')) ) as distance, t.manufacturer_code modelCode, (select DICT_LABEL FROM sys_dict_data where DICT_TYPE = 'recorder_device_mfgr_code' AND DICT_VALUE = t.manufacturer_code limit 1) modelName,
case when IFNULL(dct.user_device_coll_id, 0) = 0 then '0' else '1' end isMonitor,
t.longitude, t.latitude, t.device_status from vm_order_recorder_devices o inner join vm_recorder_device_info_t t on t.device_code = o.device_code LEFT JOIN vm_tenant_device_common_rel_t rel ON rel.device_code = o.device_code and rel.tenant_id = o.tenant_id and rel.industry_code = o.industry_code and rel.delete_flag = 0 and rel.device_type = 3
LEFT JOIN vm_user_device_collection_t dct ON dct.coll_obj_code = t.device_code AND dct.coll_obj_type = '12' AND dct.user_id = #{param.userId}
where o.delete_flag = '0' and t.delete_flag = '0' and o.ord_status in (0,1,2)
and ST_Distance_Sphere( ST_GeomFromText(CONCAT('POINT(',#{param.longitude},' ',#{param.latitude},')')), ST_GeomFromText(CONCAT('POINT(',t.longitude,' ',t.latitude,')')) ) <= #{param.radius}
${param.dataScope} group by t.device_code order by t.id
limit #{param.limitSize}

SELECT distinct dev.device_code, (case when length(IFNULL(tdr.device_name, '')) = 0 then dev.device_name else tdr.device_name end ) as device_name, dev.device_status, dev.latitude, dev.longitude, dev.site_code FROM vm_recorder_device_info_t dev left join vm_order_recorder_devices t1 on dev.device_code = t1.device_code left join vm_tenant_device_common_rel_t tdr on tdr.device_code = t1.device_code and tdr.tenant_id = t1.tenant_id and tdr.industry_code = t1.industry_code and tdr.delete_flag = 0 and tdr.device_type = 3 where dev.delete_flag = '0' AND t1.delete_flag = '0' AND t1.ord_status IN ( 0, 1, 2 )
AND dev.province_code = #{param.provinceId}
AND dev.city_code = #{param.cityId}
AND dev.county_code = #{param.countyId}
AND dev.town_code = #{param.townCode}
${param.dataScope}

select c.channel_code, c.device_code as parent_device_code, c.channel_status as status from vm_recorder_channel_info_t c where c.delete_flag = '0' and c.device_code in ( select channel.device_code from vm_recorder_channel_info_t channel where channel.delete_flag = '0' and channel.channel_code in
#{item}
)

select distinct , (case when length(IFNULL(rel.device_name, '')) = 0 then m.device_name else rel.device_name end ) device_name, (CASE WHEN od.ord_status in ('0','1','2') THEN '0' WHEN od.ord_status = '3' THEN '2' WHEN od.ord_status = '4' THEN '1' END) orderStatus, (CASE WHEN od.ord_status in ('0','1','2') THEN '有效' WHEN od.ord_status = '3' THEN '退订' WHEN od.ord_status = '4' THEN '失效' END) orderStatusName from vm_recorder_device_info_t m join vm_order_recorder_devices od on od.device_code = m.device_code left join vm_tenant_device_common_rel_t rel ON rel.device_code = m.device_code and rel.tenant_id = od.tenant_id and rel.industry_code = od.industry_code and rel.delete_flag = '0' and rel.device_type = '3'
and m.device_code in
#{item}
${dataScope}
